147|  if (!timestamp) return '';
148|  const value = new Date(timestamp);
149|  if (Number.isNaN(value.getTime())) return '';
150|  return new Intl.DateTimeFormat(undefined, {
151|    weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
152|  }).format(value);
153|}
