155|const FULFILLMENT_STAGES = [
156|  ['collecting', 'Collecting'],
157|  ['ordered', 'Ordered'],
158|  ['ready', 'Ready'],
159|  ['picked_up', 'Picked up'],
160|  ['distributed', 'Handed out'],
161|];
162|
163|function renderFulfillment() {
164|  const board = session && session.fulfillment;
165|  if (!board) return;
166|  const active = Math.max(0, FULFILLMENT_STAGES.findIndex(([status]) => status === board.status));
167|  elements.statusSteps.textContent = '';
168|  FULFILLMENT_STAGES.forEach(([status, label], index) => {
169|    const item = node('li', index < active ? 'done' : index === active ? 'current' : '');
170|    if (index === active) item.setAttribute('aria-current', 'step');
171|    item.append(node('span', 'status-step-marker', index < active ? '✓' : String(index + 1)));
172|    item.append(node('span', 'status-step-label', label));
173|    elements.statusSteps.append(item);
174|  });
175|  elements.statusCurrent.textContent = board.label || 'Collecting drinks';
176|  elements.statusHint.textContent = board.hint || '';
177|  elements.statusNote.hidden = !board.note;
178|  elements.statusNote.textContent = board.note ? `Organizer note: ${board.note}` : '';
179|  elements.statusUpdated.textContent = board.updated_at
180|    ? `Updated ${formatDeadline(board.updated_at)}` : 'No pickup update yet';
181|}
182|
183|function setSession(updated) {
184|  session = updated;
185|  const serverTime = new Date(updated.server_now).getTime();
186|  if (Number.isFinite(serverTime)) serverOffsetMs = serverTime - Date.now();
187|  deadlineTransitionHandled = !updated.accepting_orders;
188|}
189|
190|function deadlineRemaining() {
191|  if (!session) return 0;
192|  const deadline = new Date(session.deadline_at || session.expires_at).getTime();
193|  return Number.isFinite(deadline) ? deadline - (Date.now() + serverOffsetMs) : 0;
194|}
