Read text file `app/static/app.js`.
1|/* Entry page behaviour: choose a collection path, create a group room, or
2|   import a sheet. Both paths continue through the same preview and cart flow. */
3|
4|const $ = (id) => document.getElementById(id);
5|const statusBox = $('status');   // not `status`: window.status is a real global
6|const groupStatusBox = $('group-status');
7|let pendingFile = null;
8|let availableStores = [];
9|let matchingStores = [];
10|let activeStoreIndex = -1;
11|
12|/* --- first-time organizer hint ----------------------------------------- */
13|
14|function setEntryOnboarding(open, moveFocus) {
15|  const guide = $('entry-onboarding');
16|  const reopen = $('show-entry-onboarding');
17|  guide.hidden = !open;
18|  reopen.hidden = open;
19|  if (moveFocus) (open ? $('dismiss-entry-onboarding') : reopen).focus();
20|}
21|
22|$('dismiss-entry-onboarding').addEventListener('click', () => {
23|  if (window.BobaOnboarding) window.BobaOnboarding.dismiss('entry');
24|  setEntryOnboarding(false, true);
25|});
26|
27|$('show-entry-onboarding').addEventListener('click', () => {
28|  if (window.BobaOnboarding) window.BobaOnboarding.show('entry');
29|  setEntryOnboarding(true, true);
30|});
31|
32|/* --- collection path ---------------------------------------------------- */
33|
34|function selectPath(which) {
35|  const isGroup = which === 'group';
36|  $('group-path').hidden = !isGroup;
37|  $('sheet-path').hidden = isGroup;
38|  $('choose-group').classList.toggle('on', isGroup);
39|  $('choose-sheet').classList.toggle('on', !isGroup);
40|  $('choose-group').setAttribute('aria-expanded', String(isGroup));
41|  $('choose-sheet').setAttribute('aria-expanded', String(!isGroup));
42|  if (window.history && window.history.replaceState) {
43|    window.history.replaceState(null, '', `/?method=${which}`);
44|  }
45|}
46|
47|$('choose-group').addEventListener('click', () => selectPath('group'));
48|$('choose-sheet').addEventListener('click', () => selectPath('sheet'));
49|document.querySelectorAll('[data-onboarding-method]').forEach((link) => {
50|  link.addEventListener('click', (event) => {
51|    if (event.button > 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
52|    event.preventDefault();
53|    const which = link.getAttribute('data-onboarding-method');
54|    selectPath(which);
55|    window.requestAnimationFrame(() => {
56|      $(`choose-${which}`).scrollIntoView({ behavior: 'smooth', block: 'center' });
57|    });
58|  });
59|});
60|
61|/* --- tabs ---------------------------------------------------------------- */
62|
63|function showTab(which) {
64|  const isFile = which === 'file';
65|  $('tab-file').classList.toggle('on', isFile);
66|  $('tab-link').classList.toggle('on', !isFile);
67|  $('tab-file').setAttribute('aria-selected', String(isFile));
68|  $('tab-link').setAttribute('aria-selected', String(!isFile));
69|  $('panel-file').hidden = !isFile;
70|  $('panel-link').hidden = isFile;
71|}
72|$('tab-file').addEventListener('click', () => showTab('file'));
73|$('tab-link').addEventListener('click', () => showTab('link'));
74|
75|/* --- status -------------------------------------------------------------- */
76|
77|function writeStatus(target, kind, title, detail) {
78|  target.className = 'status ' + kind;
79|  target.textContent = '';
80|  if (title) {
81|    const strong = document.createElement('strong');
82|    strong.textContent = title;
83|    target.append(strong);
84|  }
85|  if (detail) target.append(document.createTextNode(detail));
86|}
87|function say(kind, title, detail) { writeStatus(statusBox, kind, title, detail); }
88|function clearStatus() { statusBox.className = 'status'; statusBox.textContent = ''; }
89|
90|/* --- store search ------------------------------------------------------- */
91|
92|function storeText(store) {
93|  return [store.name, store.address, store.city, store.state, store.zip]
94|    .filter(Boolean).join(' ').toLocaleLowerCase();
95|}
96|
97|function storeLabel(store) {
98|  const place = [store.city, store.state].filter(Boolean).join(', ');
99|  const zip = store.zip ? ` ${store.zip}` : '';
100|  return place ? `${store.name} — ${place}${zip}` : store.name;
101|}
102|
103|function closeStoreResults() {
104|  $('store-results').hidden = true;
105|  $('store-search').setAttribute('aria-expanded', 'false');
106|  $('store-search').removeAttribute('aria-activedescendant');
107|  activeStoreIndex = -1;
108|}
109|
110|function setActiveStore(index) {
111|  const options = [...$('store-results').querySelectorAll('.store-result')];
112|  if (!options.length) return;
113|  activeStoreIndex = (index + options.length) % options.length;
114|  options.forEach((option, optionIndex) => {
115|    const active = optionIndex === activeStoreIndex;
116|    option.classList.toggle('active', active);
117|    option.setAttribute('aria-selected', String(active));
118|  });
119|  const active = options[activeStoreIndex];
120|  $('store-search').setAttribute('aria-activedescendant', active.id);
121|  active.scrollIntoView({ block: 'nearest' });
122|}
123|
124|function chooseStore(store) {
125|  $('group-store').value = store.restaurant_id;
126|  $('store-search').value = storeLabel(store);
127|  $('group-submit').disabled = false;
128|  closeStoreResults();
129|  writeStatus(groupStatusBox, '', '', '');
130|}
131|
132|function renderStoreResults() {
133|  const results = $('store-results');
134|  const query = $('store-search').value.toLocaleLowerCase().trim();
135|  results.textContent = '';
136|  activeStoreIndex = -1;
137|  if (!query) {
138|    matchingStores = [];
139|    closeStoreResults();
140|    return;
141|  }
142|
143|  const terms = query.split(/\s+/).filter(Boolean);
144|  matchingStores = availableStores
145|    .filter((store) => terms.every((term) => storeText(store).includes(term)))
146|    .sort((left, right) => {
147|      const score = (store) => {
148|        const name = String(store.name || '').toLocaleLowerCase();
149|        const city = String(store.city || '').toLocaleLowerCase();
150|        const zip = String(store.zip || '').toLocaleLowerCase();
151|        if (zip === query) return 0;
152|        if (name.startsWith(query)) return 1;
153|        if (city.startsWith(query)) return 2;
154|        return 3;
155|      };
156|      return score(left) - score(right) || storeLabel(left).localeCompare(storeLabel(right));
157|    })
158|    .slice(0, 10);
159|
160|  if (!matchingStores.length) {
161|    const empty = document.createElement('p');
162|    empty.className = 'store-no-results';
163|    empty.textContent = 'No stores match that search.';
164|    results.append(empty);
165|  } else {
166|    matchingStores.forEach((store, index) => {
167|      const option = document.createElement('button');
168|      option.type = 'button';
